import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {EdgeDatabaseService,EdgeOutboxPersistence} from '../tridentpos/packages/edge/dist/index.js';
import {createPosFastifyApp} from '../tridentpos/packages/pos-edge-runtime/dist/index.js';
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'r2-'));
const db=new EdgeDatabaseService({databasePath:path.join(dir,'db')});
const outbox=new EdgeOutboxPersistence(db);
const app=await createPosFastifyApp({edgeDb:db,outbox,organizationId:'A',branchId:'A',stationId:'A'});
const request=async(a,url,payload)=>{const r=await a.inject({method:'POST',url,payload});return {status:r.statusCode,body:r.json()};};
const opened=await request(app,'/turnos/apertura',{responsibleUserId:'OP',openingCashFloat:'0.0000'});
assert.equal(opened.status,201);const id=opened.body.turno.id;
for (const operatorPin of [undefined,'INVALID']) {
 const version=db.queryRowSafe('SELECT version FROM turnos_caja WHERE id=?',id).version;
 const r=await request(app,`/turnos/${id}/movimientos`,{operatorUserId:'OP',operatorPin,movementType:'VENTA_EFECTIVO',amount:'1.0000',reason:'probe',expectedVersion:Number(version)});
 assert.equal(r.status,201);
 console.log(JSON.stringify({finding:'BLK-01',composition:'no pinValidator',pin:operatorPin??'omitted',status:r.status,persistedMovements:db.queryRowsSafe('SELECT * FROM movimientos_caja WHERE turno_caja_id=?',id).length}));
}
const validators={validatePin:async()=>true};
for (const identity of [{organizationId:'B',branchId:'A',stationId:'A'},{organizationId:'A',branchId:'B',stationId:'A'},{organizationId:'A',branchId:'A',stationId:'B'}]) {
 const foreign=await createPosFastifyApp({edgeDb:db,outbox,...identity,pinValidator:validators});
 for(const route of ['operadores','movimientos','corte-x','arqueo','corte-z']) {
  const r=await request(foreign,`/turnos/${id}/${route}`,{operatorUserId:'OP',addedByUserId:'OP',requestedByUserId:'OP',performedByUserId:'OP',closedByUserId:'OP',expectedVersion:3,movementType:'VENTA_EFECTIVO',amount:'1.0000',reason:'x',declaredCash:'2.0000'});
  assert.equal(r.status,404);assert.deepEqual(r.body,{error:'SHIFT_NOT_FOUND',message:'Shift not found'});
 }
 console.log(JSON.stringify({finding:'BLK-02',foreignIdentity:identity,routesRejected:5,status:404}));await foreign.close();
}
const arq=await request(app,`/turnos/${id}/arqueo`,{performedByUserId:'OP',declaredCash:'2.0000',expectedVersion:3});assert.equal(arq.status,200);
const closes=await Promise.all([request(app,`/turnos/${id}/corte-z`,{closedByUserId:'OP',expectedVersion:4}),request(app,`/turnos/${id}/corte-z`,{closedByUserId:'OP',expectedVersion:4})]);
assert.deepEqual(closes.map(x=>x.status).sort(),[200,409]);
const corteCount=db.queryRowsSafe('SELECT * FROM cortes_caja WHERE turno_caja_id=?',id).length;
const eventCount=db.queryRowsSafe("SELECT * FROM outbox_queue WHERE action='CorteZGenerado'").length;
assert.equal(corteCount,1);assert.equal(eventCount,1);
console.log(JSON.stringify({finding:'BLK-05',concurrentStatuses:closes.map(x=>x.status),corteCount,eventCount}));
await app.close();db.close();fs.rmSync(dir,{recursive:true,force:true});

